# Q3: append the RADEX-ladder results (s52/s53) to /output/report.json (idempotent: replaces earlier Q3 entries).
import json
P='/output/report.json'; R=json.load(open(P)); res=[x for x in R['results'] if not str(x.get('evidence','')).startswith('Q3:')]
S=json.load(open('/workspace/out/q3/s53_results.json'))
A=[{"name":"distance","value":"40 Mpc (1\" = 194 pc), vsys 2750 km/s"},{"name":"RADEX","value":"LAMDA hcn.dat, hco+.dat (H2 collisions), Tbg 2.73 K, expanding-sphere (LVG) geometry unless stated, N per 150 km/s"},
   {"name":"beam","value":"all lines smoothed to a 10\" circular beam (Xb55 J=2, Xb4f J=3, Xb47 J=4), |v-vsys|<350 km/s, pbcor, continuum-subtracted"},
   {"name":"calibration","value":"7% independent per line (flux scale+beam matching) + band-scale nuisance shared by HCN and HCO+ and by all regions: sigma 20%/10%/20% for Band 5/6/7 (baseline 'cal20'); 10%/10%/10% and 35%/15%/35% tested"},
   {"name":"priors","value":"flat in log n 3-8, log Tk 10-300, log N(HCO+) 11.5-19, log A=log N(HCN)/N(HCO+) -1..1.5; common filling eta<=1 (flat in ln eta, analytic marginalisation)"}]
def add(q,t,v,u,unit,conf,ev,extra=None):
    res.append(dict(quantity=q,target=t,value=v,uncertainty=u,unit=unit,assumptions=A+(extra or []),confidence=conf,evidence='Q3: '+ev))
E1='scripts/s53_ladder_fit.py (grid from s52_radex_grid.py) -> out/q3/s53_ladder_fit.txt, s53_results.json, s53_nT_posteriors.png'
add("Observed HCN and HCO+ J=2-1, 3-2, 4-3 ladders at the common 10\" beam (velocity-integrated Tb, K km/s, RJ, rest frame) and ladder ratios, at N, S, Bridge (N-S midpoint), disk positions E1/E2/W, Sblue and the r<8\" aperture",
 "10\" circular beam (1.9 kpc); position apertures = value of the smoothed map at the Q0 region position; disk = mean of E1,E2,W",
 "HCN 2-1/3-2/4-3 | HCO+ 2-1/3-2/4-3 [K km/s]: N 12.4/4.8/1.6 | 20.3/10.0/4.5; S 11.7/4.3/1.4 | 20.9/10.0/4.3; Bridge 13.4/5.1/1.7 | 22.7/11.2/5.0; disk(E1,E2,W) 5.1/1.3/0.19 | 9.7/4.0/1.3; Sblue 7.8/2.6/0.69 | 14.4/6.4/2.4; r<8\" 7.7/2.6/0.71 | 13.6/6.2/2.4 (per 10\" beam, r<8\" is a total flux over the aperture). HCN/HCO+ (K) at J=2,3,4: N 0.61/0.48/0.36; S 0.56/0.43/0.32; Bridge 0.59/0.46/0.34; disk 0.52/0.34/0.14; Sblue 0.54/0.40/0.29. T(2-1)/T(3-2) is 2.6 (HCN) and 2.0 (HCO+) at N, 3.8 and 2.4 in the disk; T(4-3)/T(3-2) 0.34/0.45 at N, 0.14/0.33 in the disk. Disk 4-3 HCN is only 3-12 sigma per position (W 3 sigma).",
 "stat <1% per line; the ladder carries 7% per line + the band-scale systematics (10-35% across bands); same-J HCN/HCO+ ratios are free of the band scale (+-7-10%)","K km/s; ratio","medium",E1)
def q(k,key): return S[k]['q'][key]
def fmt(k):
    d=S[k]; qq=d['q']; pr=d['probs']
    return (f"log n(H2) {qq['log n'][1]:.2f} [{qq['log n'][0]:.2f},{qq['log n'][2]:.2f}], Tkin {qq['Tk'][1]:.0f} [{qq['Tk'][0]:.0f},{qq['Tk'][2]:.0f}] K, log N(HCO+)/150 km/s {qq['log N(HCO+)'][1]:.2f} [{qq['log N(HCO+)'][0]:.2f},{qq['log N(HCO+)'][2]:.2f}], A=N(HCN)/N(HCO+) 10^{qq['log A'][1]:.2f} (10^[{qq['log A'][0]:.2f},{qq['log A'][2]:.2f}]), "
            f"P(n>1e5)={pr['P(n>1e5)']:.2f}, P(Tk>50 K)={pr['P(Tk>50)']:.2f}, P(A>1)={pr['P(A>1)']:.2f}, chi2min {d['chi2min']:.2f}")
add("Single-zone non-LTE (RADEX LVG) constraints on n(H2), Tkin, N(HCO+), N(HCN)/N(HCO+) from the full HCN+HCO+ J=2-1,3-2,4-3 ladder at 10\": N, S and Bridge positions, the r<8\" aperture and Sblue (baseline calibration scenario, medians and 16-84% of the marginal posteriors)",
 "10\" beam positions N, S, Bridge, Sblue and the r<8\" aperture; 6 data (3 J x 2 molecules), 5 free parameters (n, Tk, N(HCO+), A, eta) => 1 degree of freedom",
 f"N: {fmt('cal20|N')}. S: {fmt('cal20|S')}. Bridge: {fmt('cal20|Bridge')}. Sblue: {fmt('cal20|Sblue')}. r<8\": {fmt('cal20|ap<8\"')}. All five sit in the same region: low-to-moderate density n~1e4 (1e3.5-1e5, P(n>1e5) 0.05-0.08), warm gas (Tk>50 K at 84-89%; a cold dense island at Tk~10 K, n>1e7 is allowed at low weight), HCN thin-to-moderate (tau(HCN 3-2) median 5, 16-84% 0.16-88 at N; P(tau>1)=0.6-0.7) and an HCN column ~2-3x the HCO+ column. Thermal pressure log P/k = 6.3 [5.4,6.8] (N), 6.3 [5.5,6.9] (S) cm-3 K. Fits are acceptable (chi2min 0.06-0.6 for 1 dof) but with 1 dof this is only a consistency screen: the ladder is NOT over-constrained. The preferred low density comes mainly from T(2-1)/T(3-2)=2.0-2.6, which needs a sub-thermal ladder AND a Band 5 flux scale not too high by >20-35%; with the Band 5 scale free (B5free) n and Tk widen to n 1e3.25-1e5.25, Tk 28-160 (N); with Band 7 free: n 1e3.25-1e5, Tk 40-160.",
 "log n +-0.75 dex, Tk factor ~2 (68%); see the scenario entry","dex; K; ratio","low",E1,
 [{"name":"filling","value":"one common eta for HCN and HCO+ and all J (eta<=1; log10 eta = -1.5 at N, i.e. area x velocity filling of ~3%)"}])
rows=[]
for scn,lab in (('cal10','cal10 (10/10/10% band scales)'),('cal35','cal35 (35/15/35%)'),('ratios-only','ratios-only (band scales free)'),('B5free','Band 5 scale free'),('B7free','Band 7 scale free')):
    qq=S[f'{scn}|N']['q']; pr=S[f'{scn}|N']['probs']
    rows.append(f"{lab}: log n {qq['log n'][1]:.2f} [{qq['log n'][0]:.2f},{qq['log n'][2]:.2f}], Tk {qq['Tk'][1]:.0f} [{qq['Tk'][0]:.0f},{qq['Tk'][2]:.0f}], P(n>1e5)={pr['P(n>1e5)']:.2f}, P(A>1)={pr['P(A>1)']:.2f}")
for k,lab in (('slab','plane-parallel slab geometry'),):
    qq=S['slab|N']['q']; rows.append(f"{lab}: log n {qq['log n'][1]:.2f} [{qq['log n'][0]:.2f},{qq['log n'][2]:.2f}], Tk {qq['Tk'][1]:.0f} [{qq['Tk'][0]:.0f},{qq['Tk'][2]:.0f}] (density lower by ~0.5 dex: LVG escape probability is lower for the same N/dv)")
rows.append("H13CN limit from Q4 applied as tau(HCN 4-3)<3.8/6.4/12.8 (12C/13C=30/50/100): N log n 4.50 [3.75,5.00], Tk 112 [80,160], P(n>1e5)=0.10, identical for the three limits (the limit removes only the thick tail, tau>~4)")
ratio_only=S['profile|ratios-only|N']['allowed_frac']; cal=S['profile|cal20|N']['allowed_frac']
add("Robustness of the N, S ladder constraints to the flux-scale systematics, RADEX geometry and the H13CN opacity limit; how much the same-J HCN/HCO+ ratios alone constrain",
 "N position (S and Bridge behave the same), 10\" beam, 3 J x 2 molecules",
 "; ".join(rows)+f". Using ONLY the three same-J HCN/HCO+ ratios (independent of the band flux scales) the constraint collapses: N log n 4.75 [3.50,6.25], Tk 80 [28,160] K, A>1 only at P=0.61, {100*ratio_only:.0f}% of the (Tk,n) plane has profile chi2 within +4 of the minimum (vs {100*cal:.0f}% when the ladder normalisations are used with 20% band scales). So the density/temperature information at 10\" comes from the cross-band J-ladder normalisation (10-20% flux-scale accuracy), not from the line ratios. Conclusion robust to scenario: n~1e4-1e5, Tk>~50 K, A>~1 at the N/S/Bridge positions; P(n>1e5) is 0.08 (cal20), 0.17 (cal35), 0.21 (Band 5 free) and 0.37 (ratios-only); P(n>1e6) is 0.04-0.16.",
 "scenario spread ~0.5 dex in n; Tk 28-160 K","dex; K","medium",E1)
add("Does the 10\" ladder differ between regions? Bayesian and chi2 comparison of shared vs separate (n, Tk, N, A) for N vs S, deblended zone N vs zone S, N/S vs Bridge, and Bridge/N/S vs the disk; plus the model-free N/S ratio of HCN/HCO+ per J",
 "N, S, Bridge positions and deblended zones (s37) at the 10\" beam; disk = mean(E1,E2,W)",
 f"N vs S: no significant difference. Same-J HCN/HCO+ ratio N/S = 1.09+-0.15, 1.12+-0.16, 1.13+-0.16 at J=2,3,4 (0.6-0.9 sigma, with 7% per line systematics; the stat error alone is 0.5%). Shared-parameter model: dchi2(shared - separate) = {S['pair|cal20|N|S']['dchi2_shared_vs_sep']:.1f} for 4 extra parameters (p=0.72); ln Bayes factor (separate/shared) = {S['pair|cal20|N|S']['lnB_20']:.1f} (data favour identical parameters). Deblended zones N vs S: ratio 1.40+-0.41, 1.34+-0.46, 1.32+-0.71 (J=2,3,4), dchi2 = {S['pair|cal20|zoneN|zoneS']['dchi2_shared_vs_sep']:.1f}, p=0.56, ln B = {S['pair|cal20|zoneN|zoneS']['lnB_20']:.1f}. N or S vs Bridge: dchi2 0.2, ln B -7: identical. The same results hold for cal10 and ratios-only. Disk (E1,E2,W) vs Bridge/N/S: DIFFERENT. HCN/HCO+(4-3) Bridge/disk = 2.4+-0.3 (6.1 sigma), N/disk 2.5+-0.4 (6.6), S/disk 2.2+-0.3 (5.7); J=3: 1.36+-0.19 (2.2 sigma); J=2: 1.1+-0.16. Shared-parameter fit rejected: dchi2 = 116 (Bridge vs disk), 128 (N vs disk), 96 (S vs disk) for 4 extra parameters; ln B > +40; even with shared (n,Tk) and separate (N,A): dchi2 10.5-13.9 for 2 extra (p=0.001-0.005, ln B 3.7-5.1). The disk is colder and denser/subthermal: " + fmt('cal20|disk(E1,E2,W)') + f" (chi2min 2.0 for 1 dof, eta~0.8: formally at the filling boundary, mild tension). Cold (Tk 14-28 K) holds when the Band 5 or Band 7 scale is left free (P(Tk>50)=0.01). The disk also has the lowest S/N (4-3: W 3 sigma, E1 11, E2 20, per position). N vs S differences visible at 0.25-1\" (HCN/HCO+ 3-2 0.83-1.0 vs 0.40, Q1) wash out at 10\": the N-core contributes only ~18% (HCN) and ~10% (HCO+) of the 10\" 3-2 flux at the N position, and the two nuclei are 5\" apart, so N and S beams share the same envelope.",
 "N vs S ratio +-0.15 (7% per line); chi2 and lnB depend on the 7%/band-scale model; coarse (n,T,N) grid for the Bayes factors","ratio; chi2; ln B","medium",E1+'; the pair comparison is pair_compare() in s53')
env=[]
for nm in ('thick','mid','thin'):
    d=S[f'N_env_{nm}']; qq=d['q']; pr=d['probs']; env.append(f"core ladder {nm}: envelope HCN/HCO+ = {d['R'][0]:.2f}, {d['R'][1]:.2f}, {d['R'][2]:.2f} (J=2,3,4); log n {qq['log n'][1]:.2f} [{qq['log n'][0]:.2f},{qq['log n'][2]:.2f}], Tk {qq['Tk'][1]:.0f} [{qq['Tk'][0]:.0f},{qq['Tk'][2]:.0f}], P(n>1e5)={pr['P(n>1e5)']:.2f}, P(A>1)={pr['P(A>1)']:.2f}")
add("Two-zone check at N: ladder of the extended envelope after removing the compact core (Xb4b r<0.5\": 5.78 Jy km/s HCN, 6.28 HCO+ at 3-2) from the 10\" beam, with the core K-ladder L=T(4-3)/T(3-2)=1.0/0.8/0.57 (thick/mid/thin)",
 "N position, 10\" beam; core flux from Q4 s43; 15% error on the core flux",
 "; ".join(env)+". The core carries 18% of HCN and 10% of HCO+ at 3-2 at the 10\" beam, so the envelope has HCN/HCO+(3-2) 0.43 vs 0.48 total and a 4-3 flux lower by 32-56% than the total (HCN T(4-3)/T(3-2)=0.18-0.28 vs 0.34). The envelope is colder than the single-zone total: Tk 40-56 K [20-80] instead of 112 [56,112], with similar density (n~1e4.5, P(n>1e5)=0.12-0.25) and HCN column >1x HCO+ (A>1 at 0.95). The N-S-Bridge similarity therefore holds for the envelope too, but the single-zone Tk at N is biased high by the compact core: Tk(N) is a blend, ~50-110 K.",
 "core ladder assumption (3 cases), 15% core flux error; Xb4b may resolve out a diffuse part of the 'core' definition","K; dex","low",E1,
 [{"name":"core flux","value":"Xb4b r<0.5\" |v|<350 km/s from s43_profiles.csv, added at 10\" with unit beam response"}])
dd={k:S[f'derived|{k}'] for k in ('N','S','Bridge','disk(E1,E2,W)')}
add("Column density and implied path length of the single-zone fit (with an assumed X(HCO+)): N(H2) per 150 km/s and L=N(H2)/n(H2); beam-filling of the 10\" zone",
 "N, S, Bridge, disk at 10\"",
 f"N(HCO+)/dv: N 10^{S['cal20|N']['q']['log N(HCO+)/dv'][1]:.2f} cm-2/(km/s) (16-84%: 10^{S['cal20|N']['q']['log N(HCO+)/dv'][0]:.2f}-10^{S['cal20|N']['q']['log N(HCO+)/dv'][2]:.2f}), S 10^{S['cal20|S']['q']['log N(HCO+)/dv'][1]:.2f}, disk 10^{S['cal20|disk(E1,E2,W)']['q']['log N(HCO+)/dv'][1]:.2f}; N(HCN)/dv N 10^{S['cal20|N']['q']['log N(HCN)'][1]-2.18:.2f}. For X(HCO+)=1e-9 (factor 3-10 uncertain): log N(H2) per 150 km/s = {dd['N']['logNH2'][1]} [{dd['N']['logNH2'][0]},{dd['N']['logNH2'][2]}] (N), {dd['S']['logNH2'][1]} (S), {dd['disk(E1,E2,W)']['logNH2'][1]} (disk); path L = 10^{dd['N']['logL_pc'][1]} pc (10^[{dd['N']['logL_pc'][0]},{dd['N']['logL_pc'][2]}]) at N, 10^{dd['S']['logL_pc'][1]} pc at S, 10^{dd['disk(E1,E2,W)']['logL_pc'][1]} pc in the disk. The 10\" filling eta (area x velocity) is ~3-5% at N/S/Bridge and unconstrained in the disk (eta~0.8). The N(H2) and L inherit the degeneracy of N with n and eta (N(HCO+) 14.25-16.5 at N), and the 150 km/s reference width; they are order-of-magnitude values.",
 "N(HCO+) +-1.1 dex (16-84%); N(H2) additionally the X(HCO+) factor 3-10","cm-2; pc","low",E1,
 [{"name":"abundance","value":"X(HCO+)=1e-9 assumed (not measured here)"}])
d=S['peakTb|N']; e=S['peakTb|S']
add("Is the 0.25\" peak brightness temperature consistent with the 10\" single zone? Posterior of the zone's T_R(3-2) vs the observed 0.25\" peak T_b (N 1.46/1.56 K, S 0.79/1.87 K for HCN/HCO+)",
 "N and S, 10\" ladder fit vs Xb4b 0.25\" peaks (Q4 s43)",
 f"T_R(HCO+ 3-2) of the fitted zone: N {d['TR_HCO'][1]} K [{d['TR_HCO'][0]},{d['TR_HCO'][2]}], S {e['TR_HCO'][1]} K [{e['TR_HCO'][0]},{e['TR_HCO'][2]}]; T_R(HCN 3-2): N {d['TR_HCN'][1]} [{d['TR_HCN'][0]},{d['TR_HCN'][2]}], S {e['TR_HCN'][1]} [{e['TR_HCN'][0]},{e['TR_HCN'][2]}]. P(T_R >= observed 0.25\" peak in both lines) = {d['P_both']:.2f} (N), {e['P_both']:.2f} (S). The 0.25\" peaks (filling eta<=1) can be the same gas as the 10\" zone in ~40% of the posterior (the zone then has eta~1 at 0.25\"); otherwise the compact peaks are hotter/denser/thicker than the 10\" mean, as the Q4 N-core analysis suggested. This does not discriminate.",
 "see posterior spread","K; probability","low",E1)
R['results']=res
# recipe, interpretation, caveats
rec=[x for x in R['recipe'] if x.get('order')!=14]
rec.append({"order":14,"stage":"modelling","description":"Q3: RADEX (LVG and slab; LAMDA hcn.dat, hco+.dat; Tbg 2.73 K) grid of T_R, Tex, tau for J=2-1,3-2,4-3 of HCN and HCO+ over Tkin x n(H2) x N (per 150 km/s); Bayesian single-zone fit of the 10\" ladder with analytic marginalisation of a common filling factor and correlated band-scale nuisance; scenarios of calibration, geometry, H13CN tau limit, core subtraction; region comparison by chi2 and evidence (shared vs separate parameters)","software":"radex_lvg, radex_slab, numpy, scipy, matplotlib",
 "parameters":[{"name":"grid","value":"Tk 10,14,20,28,40,56,80,112,160,224,300 K; log n 3-8 step 0.25; log N 11.5-19 step 0.25 (per 150 km/s)"},{"name":"priors","value":"flat log n, log Tk, log N(HCO+), log A in [-1,1.5], eta<=1"},{"name":"errors","value":"stat + 7% per line + band-scale sigma (20,10,20)% baseline; alternatives 10/10/10, 35/15/35, free"},{"name":"data","value":"10\" circular beam, |v|<350 km/s, from out/s30_ratios.json; deblended zones from out/s37_deblend2.json"},{"name":"Tbg","value":"2.73","unit":"K"}],
 "scripts":["/workspace/scripts/s52_radex_grid.py","/workspace/scripts/s53_ladder_fit.py","/workspace/scripts/s54_update_report_q3.py"]})
R['recipe']=rec
T=(" Q3: At the common 10\" beam (1.9 kpc) the HCN/HCO+ J=2-1,3-2,4-3 ladders of the N nucleus, S nucleus, the bridge between them, Sblue and the r<8\" aperture are indistinguishable (same-J ratio differences <=13+-15%, dchi2 2 for 4 extra parameters, ln Bayes factor favouring identical parameters). A single-zone RADEX fit gives moderate density (n~1e4-1e5 cm-3, 1e3.5-1e5 at 68%), warm gas (Tk>50 K in ~85%), HCN column 2-3x HCO+ and an area-velocity filling of ~3%; this depends on the Band 5/6/7 flux scales (ratios alone leave n 1e3.5-1e6 and Tk 30-160 K unconstrained) and on the single-zone assumption (removing the compact N core lowers Tk to ~40-56 K). Densities >1e6 cm-3 are not demanded but not excluded at the N core (Q4). The one significant region contrast at 10\" is the outer disk (E1, E2, W) vs the central/bridge gas: HCN/HCO+(4-3) lower by 2.2-2.5 (6 sigma) and T(4-3)/T(3-2) lower, which a single zone reads as colder gas (Tk~14-28 K, n~1e5, dchi2~100 vs shared parameters); this is robust to freeing the Band 5 or Band 7 scale but rests on low-S/N 4-3 detections (3-20 sigma) and on Band 7 sensitivity to extended emission. The 0.25-1\" N-S ratio difference (Q1) is smeared out at 10\", so the 'nucleus vs outflow vs disk' question is answered at 10\" only for 'central vs outer disk'; N vs S vs outflow base need the high-resolution J=3-2 pair only.")
if ' Q3: At the common 10' not in R['interpretation']: R['interpretation']+=T
cav=["Q3: The 10\" ladder fits have 6 data for 5 parameters (1 dof); posteriors are prior- and grid-weighted (flat in log n, Tk, N, A; 0.25 dex grid; 11 Tk values), so quoted intervals are marginals, not confidence regions, and at the grid edge (Tk 112 [56,112]) the upper end is the grid step.",
     "Q3: Band 5/6/7 flux scales (10-35%) and the missing flux of the compact Band 5/7 observations (extended disk emission) directly set the n,Tk results; there is no overlapping line to calibrate the bands against each other (Xb4f vs Xb47/Xb55 was not testable). The disk 4-3 low-S/N and Band 7 short-baseline coverage are the main risks for the disk contrast.",
     "Q3: Single-zone, one filling factor for both molecules and all J, 150 km/s reference width, LVG sphere: different filling of HCN and HCO+, a hot compact component (Q4: N core T_b ratio ~1) and velocity-resolved ratios are not modelled; plane-parallel geometry lowers n by ~0.5 dex. The cold dense (10 K, >1e7) islands in the posterior are low-weight but not excluded. N(H2) needs an abundance assumption (X(HCO+)=1e-9 used for scale only).",
     "Q3: At 10\" the N and S apertures are 5\" apart and share most of their beam; the 'zone' deblend (s37) has chi2_red 9-99, so zone-level N vs S differences have 30-70% errors. H13CN limits (Q4) are beam-average and only exclude tau(HCN 4-3)>~4-13. Confirmation requires matched-beam H13CN/H13CO+ and J=2-1 at <3\" or CO ladders for the kinetic temperature."]
for c in cav:
    if c not in R['caveats']: R['caveats'].append(c)
json.dump(R,open(P,'w'),indent=1); print(len(R['results']),'results')
